import test from 'node:test';import assert from 'node:assert/strict';
import {PhysicsWorld} from '../world.mjs';import {beginRecovery,stepRecovery} from '../recovery.mjs';
const ground=[[-10,0,-10,10,0,10,10,0,-10],[-10,0,-10,-10,0,10,10,0,10]];
function scene(wall=false){const w=new PhysicsWorld();w.addTile({id:'a',volume:{polygon:[[-10,-10],[10,-10],[10,10],[-10,10]],minY:-10,maxY:20},triangles:[...ground,...(wall?[[.5,0,-5,.5,5,-5,.5,5,5],[.5,0,-5,.5,5,5,.5,0,5]]:[])]});const b=w.addBody({id:'b',position:[0,.3,0]});for(let i=0;i<60;i++)w.advance(1/120);return {w,b};}
test('recovery walks continuously on real contacts and preserves gravity instead of teleporting',()=>{const {w,b}=scene();assert.ok(beginRecovery(b,{position:[1,0,0],maxDistance:2},[0,.3,0]));let previous=b.position[0];for(let i=0;i<600;i++){stepRecovery(b,1/120);w.advance(1/120);assert.ok(Math.abs(b.position[0]-previous)<.006);previous=b.position[0];assert.ok(Math.abs(b.position[1]-.3)<1e-6);}assert.ok(b.position[0]>.94);assert.ok(b.settled);});
test('recovery cannot tunnel through a real wall and expires without moving position directly',()=>{const {w,b}=scene(true);beginRecovery(b,{position:[1,0,0]},[0,.3,0]);for(let i=0;i<800;i++){stepRecovery(b,1/120);w.advance(1/120);assert.ok(b.position[0]<=.201);}assert.equal(b.recovery,undefined);assert.equal(beginRecovery(b,{position:[-1,0,0]},[0,.3,0]),false);});
test('distant targets are rejected and airborne bodies receive no locomotion impulse',()=>{const {b}=scene();assert.equal(beginRecovery(b,{position:[3,0,0]},[0,.3,0]),false);const a={position:[0,5,0],velocity:[1,-2,3],contact:false};beginRecovery(a,{position:[1,5,0]},[0,0,0]);stepRecovery(a,.1);assert.deepEqual(a.velocity,[1,-2,3]);});
